import {showUserSettings} from './user-settings.mjs';
let currentAccount={};
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫';
let accountRole='Broke';let accountName='';let profile={name:'Your name',bio:'On my journey to be debt-free.',goal:50000000,paid:0,next:'Đặt một mục tiêu nhỏ cho tháng này.',thanks:''},tab='journey',api;
try{const p=JSON.parse(localStorage.getItem('debtfreelately-profile'));if(p&&typeof p.name==='string'&&Number.isFinite(p.goal)&&p.goal>0&&Number.isFinite(p.paid)&&p.paid>=0&&p.paid<=p.goal)profile={...profile,...p};}catch{}
function write(){try{localStorage.setItem('debtfreelately-profile',JSON.stringify(profile));}catch{api.toast('Không lưu được trên thiết bị. Thay đổi chỉ tồn tại trong phiên này.');}}
export function initBroke(callbacks){api=callbacks;const root=document.createElement('section');root.id='broke-dashboard';root.setAttribute('aria-label','Trang cá nhân');document.body.append(root);root.addEventListener('keydown',event=>{const card=event.target.closest('[data-supporter-name]');if(card&&(event.key==='Enter'||event.key===' ')){event.preventDefault();card.click();}});root.addEventListener('click',ev=>{const supporter=ev.target.closest('[data-supporter-name]');if(supporter){api.supporterMessage({id:supporter.dataset.supporterName,name:supporter.dataset.supporterName,initials:supporter.dataset.supporterInitials,color:supporter.dataset.supporterColor});return;}const b=ev.target.closest('[data-broke]');if(!b)return;const action=b.dataset.broke;if(action==='settings'||action==='edit')showUserSettings(currentAccount,{modal:api.modal,close:api.close,toast:api.toast,logout:api.logout,onSave:updated=>{currentAccount=updated;accountName=updated.name;render();}});if(action==='goal')edit();if(action==='role')api.role();if(action==='create-card')api.createCard();if(action==='post')api.post();if(action==='posts'){document.body.classList.remove('broke-mode');api.posts();}if(action==='journey'||action==='activity'){tab=action;render();}if(action==='thanks')thanks();if(action==='supporters')supporters();if(action==='logout')api.logout();if(action==='saved')api.saved();if(action==='messages')api.messages();if(action==='discover'){document.body.classList.remove('broke-mode');api.discover();}if(action==='home')showBroke();});render();}
export function showBroke(account){if(account){currentAccount={...account};if(account.designPreview){try{currentAccount={...account,...JSON.parse(localStorage.getItem('debtfreelately-preview-settings')||'{}')};}catch{}}accountName=currentAccount.name;accountRole=account.role||'Broke';}document.body.classList.remove('onboarding');document.body.classList.add('broke-mode');render();window.scrollTo(0,0);document.querySelector('#broke-title')?.focus({preventScroll:true});}
export function hideBroke(){document.body.classList.remove('broke-mode');}
function render(){const root=document.querySelector('#broke-dashboard');if(!root)return;const posts=api?.getPosts()||[],pledged=posts.reduce((s,p)=>s+p.pledged,0),pct=Math.round(profile.paid/profile.goal*100);root.innerHTML=`<div class="broke-top"><a href="#" class="broke-brand" data-broke="home"><img src="assets/debtfreelately-logo-transparent.png" alt="DebtFreeLately"></a><nav class="broke-top-nav" aria-label="Điều hướng trang cá nhân"><a class="broke-management-link" href="/my-cards">▤ Thẻ đã gửi</a><button class="selected" data-broke="home">⌂ <span>Home</span></button><button data-broke="discover">◈ <span>Tìm Broke</span></button><button data-broke="saved">☆ <span>Đã lưu</span></button><button data-broke="messages">✉ <span>Tin nhắn</span></button><button type="button" data-notifications>♧ <span>Thông báo</span></button>${currentAccount.isAdmin?'<a class="broke-management-link" href="/admin">Quản trị</a>':''}</nav></div><div class="broke-layout"><div class="broke-center"><div class="profile-overview panel"><button type="button" class="profile-portrait" data-broke="settings" aria-label="Mở cài đặt người dùng" title="Cài đặt người dùng">${currentAccount.photo?`<img class="profile-account-photo" src="${e(currentAccount.photo)}" alt="Ảnh đại diện">`:`<span>${e((accountName||profile.name).charAt(0))}</span>`}<b aria-hidden="true">✦</b></button><div class="profile-identity"><div class="profile-name-row"><h1 id="broke-title" tabindex="-1">${e(accountName||profile.name)}</h1></div><p>${e(profile.bio)}</p></div><div class="profile-metric"><span>♡</span><div><small>Total commitments</small><strong>${cash(pledged)}</strong></div></div><div class="profile-metric"><span>♧</span><div><small>My stories</small><strong>${posts.length} ${posts.length===1?'story':'stories'}</strong></div></div></div><section class="gratitude panel"><div class="panel-heading"><div><h2><span>♡</span> Wall of Gratitude</h2><p>The ones who stood by me when it mattered most.</p></div></div><div class="gratitude-demo-label">GIAO DIỆN MINH HỌA · CHƯA CÓ HỖ TRỢ THẬT</div><div class="supporter-marquee"><div class="supporter-track"><div class="supporter-grid">${[['CW','@CryptoWhale','Top Supporter','12.000.000 ₫','Keep going! 💪','gold'],['TL','@QuyTamLong','Kind Supporter','6.500.000 ₫','You can do it! 🌱','pink'],['DB','@DiamondBro_VN','Early Supporter','5.000.000 ₫','Always here for you.','blue']].map(([initial,name,badge,amount,message,color])=>`<article class="supporter ${color}" role="button" tabindex="0" data-supporter-name="${name}" data-supporter-initials="${initial}" data-supporter-color="${color}" aria-label="Nhắn tin với ${name}"><div class="supporter-person"><div class="supporter-avatar">${initial}</div><div><strong>${name}</strong><small>${color==='gold'?'♛':'♡'} ${badge}</small></div></div><b>+${amount}</b><p>“${message}”</p><span class="sample-tag">Mẫu</span></article>`).join('')}</div></div></div><div class="gratitude-foot"><span>Every kindness deserves to be remembered.</span></div></section><section class="journey-banner"><div><h2>Never Taken for Granted.</h2><p>Every kindness counts.</p></div></section><div class="broke-shortcuts">${[['♙','My Profile','edit'],['▤','My Stories','posts'],['◎','My Goals','goal'],['◷','Activity','activity'],['＋','Share Story','post'],['♡','Say Thanks','thanks']].map(([icon,title,action])=>`<button data-broke="${action}"><span>${icon}</span>${title}</button>`).join('')}</div><section class="journey-detail panel"><div class="journey-tabs"><button data-broke="journey" class="${tab==='journey'?'selected':''}">▥ My Journey</button><button data-broke="activity" class="${tab==='activity'?'selected':''}">◷ Activity</button></div>${tab==='journey'?`<div class="journey-body"><div><span class="broke-eyebrow">ONE DAY AT A TIME</span><h3>Your next chapter starts here.</h3><p>Ghi lại tiến độ của chính bạn, đặt mục tiêu vừa sức và chia sẻ câu chuyện khi bạn sẵn sàng.</p><button class="broke-primary" data-broke="goal">Update my journey ↗</button></div><div class="journey-summary"><div><span>Đã tự ghi nhận trả</span><strong>${cash(profile.paid)}</strong></div><div><span>Cam kết từ cộng đồng</span><strong>${cash(pledged)}</strong></div><small>Cam kết chưa phải tiền đã nhận. Tiến độ do bạn tự cập nhật.</small></div></div>`:`<div class="activity-list">${posts.length?posts.map(p=>`<div><span class="activity-icon">▤</span><div><strong>${e(p.title)}</strong><p>Khoản nợ ${cash(p.amount)} · Cam kết ${cash(p.pledged)}</p></div><button data-broke="posts" aria-label="Xem bài đăng">↗</button></div>`).join(''):'<div><span class="activity-icon">🌱</span><div><strong>Một khởi đầu mới đang chờ bạn.</strong><p>Chưa có bài đăng. Chia sẻ câu chuyện đầu tiên của bạn.</p></div><button data-broke="post" aria-label="Tạo bài đăng">＋</button></div>'}${profile.thanks?`<div><span class="activity-icon">♡</span><div><strong>Lời cảm ơn của bạn · bản nháp riêng tư</strong><p>${e(profile.thanks)}</p></div></div>`:''}</div>`}</section><p class="broke-disclaimer">Không có thanh toán trong bản thử nghiệm. Hồ sơ và tiến độ chỉ được lưu trên trình duyệt này.</p></div><div class="broke-right"><section class="profile-primary-actions"><button data-broke="discover"><span aria-hidden="true">◈</span><strong>Tìm Broke</strong><b aria-hidden="true">↗</b></button><button data-broke="create-card"><span aria-hidden="true">＋</span><strong>Add Thêm Thẻ báo nợ</strong><b aria-hidden="true">↗</b></button></section><section class="quote-card"><div><span>“</span><blockquote>A friend in need<br>is a friend indeed.</blockquote><i></i><img src="assets/debtfreelately-logo-transparent.png" alt="DebtFreeLately"></div></section><div class="gentle-note"><span>♧</span><p>You are more than your debt.<br><strong>And you don't have to do this alone.</strong></p></div></div></div>`;startSupporterMarquee();}
function edit(){api.modal(`<div class="eyebrow">MY PROFILE & JOURNEY</div><h2>A fresh start, your way.</h2><form id="broke-profile-form"><label for="bp-name">Tên hiển thị / biệt danh</label><input id="bp-name" name="name" maxlength="50" required value="${e(profile.name)}"><label for="bp-bio">Giới thiệu ngắn</label><input id="bp-bio" name="bio" maxlength="120" value="${e(profile.bio)}"><label for="bp-goal">Tổng mục tiêu trả nợ (VNĐ)</label><input id="bp-goal" name="goal" type="number" min="1000" max="1000000000000" step="1000" required value="${profile.goal}"><label for="bp-paid">Đã trả — do bạn tự ghi nhận (VNĐ)</label><input id="bp-paid" name="paid" type="number" min="0" max="1000000000000" step="1000" required value="${profile.paid}"><label for="bp-next">Mục tiêu tiếp theo</label><input id="bp-next" name="next" maxlength="140" value="${e(profile.next)}"><div class="info-box">Đây là nhật ký cá nhân, không xác nhận hoặc thực hiện thanh toán.</div><div class="form-error" id="bp-error" role="alert"></div><button class="dark">Lưu hồ sơ</button></form>`);document.querySelector('#broke-profile-form').onsubmit=ev=>{ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target));d.goal=Number(d.goal);d.paid=Number(d.paid);d.name=d.name.trim();if(!d.name||!Number.isFinite(d.goal)||d.goal<1000||d.goal>1e12||!Number.isFinite(d.paid)||d.paid<0||d.paid>d.goal){document.querySelector('#bp-error').textContent='Vui lòng điền tên và số tiền hợp lệ; số đã trả không vượt mục tiêu.';return;}profile={...profile,...d};write();api.close();render();api.toast('Đã lưu hồ sơ và tiến độ trên thiết bị.');};}
function thanks(){api.modal(`<div class="eyebrow">A LITTLE GRATITUDE</div><h2>Every kindness counts.</h2><p>Viết một lời cảm ơn cho những người đã đồng hành. Bản thử nghiệm chỉ lưu riêng tư trên thiết bị, chưa gửi cho người khác.</p><form id="broke-thanks"><label for="thanks-note">Lời cảm ơn của bạn</label><textarea id="thanks-note" name="note" maxlength="1000" required>${e(profile.thanks)}</textarea><button class="dark">Lưu lời cảm ơn riêng tư</button></form>`);document.querySelector('#broke-thanks').onsubmit=ev=>{ev.preventDefault();const note=new FormData(ev.target).get('note').trim();if(!note)return;profile.thanks=note;write();api.close();tab='activity';render();api.toast('Đã lưu bản nháp. Chưa gửi cho người khác.');};}
function supporters(){api.modal('<div class="eyebrow">MY SUPPORTERS</div><h2>A little help goes a long way.</h2><p>Bạn chưa có người hỗ trợ được xác nhận. Các thẻ trên Wall of Gratitude là dữ liệu minh họa thiết kế.</p><div class="info-box">Danh sách hỗ trợ thật sẽ được kết nối khi có tài khoản, dữ liệu dùng chung và hệ thống thanh toán.</div>');}




function startSupporterMarquee(){const track=document.querySelector('#broke-dashboard .supporter-track'),group=track?.querySelector('.supporter-grid');if(!group)return;for(const card of [...group.children]){const repeat=card.cloneNode(true);repeat.setAttribute('aria-hidden','true');repeat.tabIndex=-1;group.append(repeat);}const clone=group.cloneNode(true);clone.setAttribute('aria-hidden','true');clone.querySelectorAll('[data-supporter-name]').forEach(card=>card.tabIndex=-1);track.append(clone);}








